do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$1Life Healthcare (One Medical)$q$,$q$public_company$q$),($q$Anthropic$q$,$q$private_company$q$),($q$Rivian$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$On February 22, 2023, we acquired 1Life Healthcare, Inc. (One Medical), for cash consideration of approximately $
3.5
 billion, net of cash acquired, to provide healthcare options for customers.$q$),(2,$q$The net loss of $(2.3) billion in 2024 is primarily from the marketable securities loss from our equity investment in Rivian Automotive, Inc. (“Rivian”).$q$),(3,$q$which primarily reflect investments in convertible notes from Anthropic, PBC (“Anthropic”), including $2.7 billion we invested in 2025.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$invests$q$,$q$AMZN$q$,$q$Anthropic$q$,$q${3}$q$::int[],$q${mdna}$q$::text[],null,null,null,null),(2,$q$invests$q$,$q$AMZN$q$,$q$Rivian$q$,$q${2}$q$::int[],$q${mdna}$q$::text[],null,null,null,null),(3,$q$acquires$q$,$q$AMZN$q$,$q$1Life Healthcare (One Medical)$q$,$q${1}$q$::int[],$q${notes}$q$::text[],null,null,null,null);
create function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$Intel$q$ then ticker=$q$INTC$q$ when $q$Oracle$q$ then ticker=$q$ORCL$q$ when $q$AMD$q$ then ticker=$q$AMD$q$ when $q$CoreWeave$q$ then ticker=$q$CRWV$q$ when $q$TSMC$q$ then ticker=$q$TSM$q$ when $q$Tesla$q$ then ticker=$q$TSLA$q$ when $q$Uber Eats$q$ then ticker=$q$UBER$q$ when $q$AMZN$q$ then ticker=$q$AMZN$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$AMZN M6 group 1$q$,'claude-sonnet-5-5',155099,2150,0.4556,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1018724/000101872426000004/amzn-20251231.htm$q$,r.sec[k],t,true,$q$2026-02-06$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;